do $$ declare items jsonb:='[{"id":"00000000-0000-0000-0000-000000004530","course_id":"00000000-0000-0000-0000-000000004520","start_time":"08:00","end_time":"09:20","location":"204"},{"id":"00000000-0000-0000-0000-000000004531","course_id":"00000000-0000-0000-0000-000000004521","start_time":"09:30","end_time":"10:50","location":"308"}]';d date:=(date_trunc('week',now() at time zone 'Asia/Bishkek')+interval '70 weeks')::date;from_at timestamptz;to_at timestamptz;
begin
 from_at:=d::timestamp at time zone 'Asia/Bishkek';to_at:=(d+1)::timestamp at time zone 'Asia/Bishkek';
 perform public.save_weekly_schedule('00000000-0000-0000-0000-000000004510',1,items,0,'00000000-0000-0000-0000-000000004540');
 perform public.save_weekly_schedule('00000000-0000-0000-0000-000000004510',1,items,0,'00000000-0000-0000-0000-000000004540');
 if public.weekly_schedule_day('00000000-0000-0000-0000-000000004510',1)->>'version'<>'1' then raise exception 'TEST FAILED idempotency';end if;
 if (select count(*) from public.schedule_catalog('00000000-0000-0000-0000-000000004510',from_at,to_at))<>2 then raise exception 'TEST FAILED indefinite repetition';end if;
 if not exists(select 1 from public.schedule_catalog('00000000-0000-0000-0000-000000004510',from_at,to_at) where title='Микроэкономика' and starts_at=from_at+interval '8 hours' and ends_at=from_at+interval '9 hours 20 minutes') then raise exception 'TEST FAILED timezone/title';end if;
 begin perform public.save_weekly_schedule('00000000-0000-0000-0000-000000004510',1,items,0,gen_random_uuid());raise exception 'TEST FAILED stale day overwrite';exception when raise_exception then if sqlerrm<>'Schedule changed. Refresh before saving' then raise;end if;end;
 begin perform public.save_weekly_schedule('00000000-0000-0000-0000-000000004510',1,jsonb_set(items,'{1,start_time}','"09:00"'),1,gen_random_uuid());raise exception 'TEST FAILED weekly overlap';exception when raise_exception then if sqlerrm<>'Lessons overlap or invalid time' then raise;end if;end;
 perform public.save_schedule_exception('00000000-0000-0000-0000-000000004530',d,true,'00000000-0000-0000-0000-000000004520','08:00','09:20','204',0);
 if (select count(*) from public.schedule_catalog('00000000-0000-0000-0000-000000004510',from_at,to_at) where cancelled)<>1 or (select count(*) from public.schedule_catalog('00000000-0000-0000-0000-000000004510',from_at+interval '7 days',to_at+interval '7 days') where cancelled)<>0 then raise exception 'TEST FAILED single-date cancellation';end if;
 perform public.save_weekly_schedule('00000000-0000-0000-0000-000000004510',1,items,1,gen_random_uuid());
 perform public.save_schedule_exception('00000000-0000-0000-0000-000000004530',d,false,'00000000-0000-0000-0000-000000004520','08:00','09:20','204',1,true);
 perform public.save_schedule_exception('00000000-0000-0000-0000-000000004530',d,false,'00000000-0000-0000-0000-000000004520','07:00','08:00','204',0);
 begin perform public.save_weekly_schedule('00000000-0000-0000-0000-000000004510',1,jsonb_set(jsonb_set(jsonb_set(items,'{0,start_time}','"08:40"'),'{1,start_time}','"07:30"'),'{1,end_time}','"08:30"'),2,gen_random_uuid());raise exception 'TEST FAILED weekly edit crossed exception';exception when raise_exception then if sqlerrm<>'Lessons overlap or invalid time' then raise;end if;end;
 if public.weekly_schedule_day('00000000-0000-0000-0000-000000004510',1)->>'version'<>'2' then raise exception 'TEST FAILED atomic exception check';end if;
 perform public.save_schedule_exception('00000000-0000-0000-0000-000000004530',d,false,'00000000-0000-0000-0000-000000004520','08:00','09:20','204',1,true);
 begin perform public.save_schedule_exception('00000000-0000-0000-0000-000000004531',d,false,'00000000-0000-0000-0000-000000004521','09:10','10:30','308',0);raise exception 'TEST FAILED exception overlap';exception when raise_exception then if sqlerrm<>'Lessons overlap or invalid time' then raise;end if;end;
 perform set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000004502',true);
 if (select count(*) from public.schedule_catalog('00000000-0000-0000-0000-000000004510',from_at,to_at))<>2 then raise exception 'TEST FAILED student reads schedule';end if;
 begin perform public.save_weekly_schedule('00000000-0000-0000-0000-000000004510',1,'[]',1,gen_random_uuid());raise exception 'TEST FAILED student manages';exception when raise_exception then if sqlerrm<>'Schedule management denied' then raise;end if;end;
 begin perform public.weekly_schedule_day('00000000-0000-0000-0000-000000004510',1);raise exception 'TEST FAILED student admin read';exception when raise_exception then if sqlerrm<>'Schedule management denied' then raise;end if;end;
 perform set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000004503',true);
 if exists(select 1 from public.schedule_catalog('00000000-0000-0000-0000-000000004510',from_at,to_at)) then raise exception 'TEST FAILED foreign read';end if;
 begin perform public.save_schedule_exception('00000000-0000-0000-0000-000000004530',d,true,'00000000-0000-0000-0000-000000004520','08:00','09:20','204',0);raise exception 'TEST FAILED foreign edit';exception when raise_exception then if sqlerrm<>'Schedule management denied' then raise;end if;end;
 if has_function_privilege('anon','public.schedule_catalog(uuid,timestamptz,timestamptz,integer)','execute') or has_function_privilege('authenticated','public.schedule_rows(uuid,timestamptz,timestamptz)','execute') then raise exception 'TEST FAILED internal/anon grant';end if;
end $$;
rollback;
